    for q in g.get("obstacles", []):
        t = p(q, None)
        if t is not None:
            obs.add(t)
    res = []
    for q in g.get("resources", []):
        t = p(q, None)
        if t is not None:
            res.append(t)

    def ok(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs

    cand = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    bestv = 10**9

    for dx, dy in cand:
        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        v = abs(nx - ox) + abs(ny - oy)
        if res:
            r = min(abs(nx - rx) + abs(ny - ry) for rx, ry in res)
            v = r * 4 + v
        if (nx, ny) in g.get("self_path", []):
            v += 2
        if v < bestv or (v == bestv and (dx, dy) < best):
            bestv = v
            best = (dx, dy)

    return [int(best[0]), int(best[1])]

